#!/usr/bin/env node
// Bundles js/*.js (ES modules) into ONE classic script: js/tonemaster.bundle.js.
// Why: many website-to-app converters load files via file:// or a plain asset loader where <script type="module"> can fail.
// No dependencies. Run:  node tools/build-bundle.js   (the shipped bundle is already built)
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'public', 'tonemaster', 'js');
const entry = 'app', mods = {}, order = [];
function load(name) {
  if (mods[name]) return; mods[name] = { exports: [] }; let src = fs.readFileSync(path.join(dir, name + '.js'), 'utf8'), deps = [];
  src = src.replace(/^import\s+\{([^}]*)\}\s+from\s+'\.\/([\w-]+)\.js';?/gm, (m, names, dep) => { deps.push(dep); (mods[name].imports ||= []).push([dep, names.split(',').map(x => x.trim().split(/\s+as\s+/)[0]).filter(Boolean)]); const n = names.split(',').map(s => s.trim()).filter(Boolean).map(s => s.replace(/\s+as\s+/, ': ')).join(', '); return `const { ${n} } = __M["${dep}"];`; });
  src = src.replace(/^export\s+(async\s+function\*?|function\*?|class|const|let)\s+([A-Za-z0-9_$]+)/gm, (m, kw, id) => { mods[name].exports.push(id); return kw + ' ' + id; });
  if (/^export\s/m.test(src)) throw new Error('Unhandled export syntax in ' + name);
  mods[name].src = src; deps.forEach(load); order.push(name);
}
load(entry);
for (const n of order) for (const [dep, names] of mods[n].imports || []) for (const x of names) if (!mods[dep].exports.includes(x)) throw new Error(`Bundle check failed: ${n}.js imports "${x}" which ${dep}.js does not export (multi-declarator export?)`);
let out = '/* ToneMaster bundle – generated by tools/build-bundle.js. Edit js/*.js, then rebuild. */\n(function(){\n"use strict";\nconst __M = {};\n';
for (const n of order) out += `__M["${n}"] = (() => {\n${mods[n].src}\nreturn { ${mods[n].exports.join(', ')} };\n})();\n`;
out += '})();\n'; fs.writeFileSync(path.join(dir, 'tonemaster.bundle.js'), out); console.log('Bundled', order.join(' → '), '(' + (out.length / 1024).toFixed(0) + ' KB)');
